function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function pick(...values) {
 for (const value of values) {
   const cleaned = clean(value);
   if (cleaned) return cleaned;
 }
 return '';
}

function inferModule(workflowName) {
 const name = clean(workflowName).toUpperCase();

 if (name.includes('M1')) return 'M1';
 if (name.includes('M2')) return 'M2';
 if (name.includes('M3')) return 'M3';
 if (name.includes('M4')) return 'M4';
 if (name.includes('M5')) return 'M5';
 if (name.includes('M6')) return 'M6';
 if (name.includes('M7')) return 'M7';
 if (name.includes('M8')) return 'M8';

 return 'SYSTEM';
}

const input = items[0]?.json || {};

const error = input.error || {};
const execution = input.execution || {};
const workflow = input.workflow || {};
const node = input.node || {};

const workflowName = pick(
 workflow.name,
 input.workflowName,
 error.workflow,
 error.workflowName
);

const nodeName = pick(
 node.name,
 input.nodeName,
 error.node,
 error.nodeName,
 execution.lastNodeExecuted
);

const errorMessage = pick(
 error.message,
 error.errorMessage,
 input.errorMessage,
 input.message
);

const errorCode = pick(
 error.code,
 error.error_code,
 input.errorCode,
 'system_unhandled_workflow_error'
);

const executionId = pick(
 execution.id,
 input.executionId
);

const module = inferModule(workflowName);

return [
 {
   json: {
     global_workflow_error: {
       module,
       workflow_name: workflowName || 'unknown_workflow',
       node_name: nodeName || 'unknown_node',
       execution_id: executionId,
       error_code: errorCode,
       error_message: errorMessage || 'Unhandled workflow error',
       raw_error: input,
       detected_at: new Date().toISOString()
     }
   }
 }
];

function makeEventId(prefix = 'evt_error') {
 return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

const input = items[0]?.json || {};
const err = input.global_workflow_error || {};

const event = {
 schema_version: 'dalia.m8.event_request.v1',
 event: {
   event_id: makeEventId('evt_global_error'),
   event_name: 'error',
   event_type: 'error',
   module: err.module || 'SYSTEM',
   status: 'error',
   level: 'ERROR',
   timestamp: new Date().toISOString(),

   trace: {
     conversation_id: '',
     session_id: '',
     parent_event_id: ''
   },

   context: {
     business_id: 'business_demo',
     environment: 'demo',
     channel: '',
     user_id: ''
   },

   correlation: {
     message_id: '',
     transaction_id: '',
     handoff_id: '',
     correlation_id: err.execution_id || '',
     trace_id: err.execution_id || ''
   },

   payload: {
     error_source: 'global_error_trigger',
     execution_id: err.execution_id || '',
     workflow_name: err.workflow_name || '',
     node_name: err.node_name || '',
     recoverable: false
   },

   error: {
     error_code: err.error_code || 'system_unhandled_workflow_error',
     error_message: err.error_message || 'Unhandled workflow error',
     error_node: err.node_name || '',
     error_workflow: err.workflow_name || ''
   },

   metadata: {
     raw_error_available: Boolean(err.raw_error),
     detected_at: err.detected_at || new Date().toISOString()
   }
 }
};

return [
 {
   json: {
     m8_event_request: event
   }
 }
];

const input = items[0]?.json || {};

return [
 {
   json: {
     schema_version: 'dalia.m8.error_logger_result.v1',
     success: true,
     result_type: 'global_error_processed',
     m8_result: input,
     processed_at: new Date().toISOString()
   }
 }
];
